create procedure CK.sGroupUserAdd
as
begin
  exec CK.sZoneUserAdd @ActorId, @ZoneId, @UserId;
  exec CK.sZoneUserAdd @UserId;
end

Test.Description:
      -- SetupConfig: {}
      create transformer on CK.sGroupUserAdd
      as
      begin
	      in all 2 statement {exec CK.sZoneUserAdd}
	      begin
		      replace all 2 {@UserId} with "@UserId, @AutoAddUserInZone";
	      end
      end

Test.ResultText:

create procedure CK.sGroupUserAdd
as
begin
  exec CK.sZoneUserAdd @ActorId, @ZoneId, @UserId, @AutoAddUserInZone;
  exec CK.sZoneUserAdd @UserId, @AutoAddUserInZone;
end

Test.Text:


      if @ActorId <= 0 throw 50000, 'Security.AnonymousNotAllowed', 1;
      exec CK.sGroupCreate @ActorId, 0, @ZoneIdResult output;
	    insert into CK.tZone default values;

Test.Description:
-- SetupConfig: {}
create transformer
as
begin
  in single statement {exec CK.sGroupCreate}
  begin
    replace first {0} with "@ParentZoneId";
  end

  in single part {insert into CK.tZone}
  begin
    add column X = 4;
  end
end

Test.ResultText:


      if @ActorId <= 0 throw 50000, 'Security.AnonymousNotAllowed', 1;
      exec CK.sGroupCreate @ActorId, @ParentZoneId, @ZoneIdResult output;
	    insert into CK.tZone( X ) values ( 4 );
